import React from "react";
import useResizeObserver from "./useResizeObserver";

// we create a hidden dom element with a div of 1rem size
// the size in pixels of this element will change with browser font size setting
const createUnitElement = () => {
  const wrapper = document.createElement("div");
  Object.assign(wrapper.style, {
    position: "fixed",
    left: "0",
    top: "0",
    width: "0px",
    height: "0px",
    overflow: "hidden",
    pointerEvents: "none",
    clip: "rect(0 0 0 0)",
    clipPath: "inset(50%)",
  });
  wrapper.setAttribute("id", "ds-fontsize-setting-observer");
  const element = document.createElement("div");
  element.style.width = "1rem";
  element.style.height = "1rem";
  wrapper.append(element);
  document.body.append(wrapper);
  return element;
};

let unitInstance: HTMLDivElement;

/**
 * Hook to get an updated REM to PIXEL factor
 * when user change browser font size setting
 */
const useRemFactor = () => {
  const [factor, setFactor] = React.useState<any>(16);
  // ensure a single element is added in body for all instances of this hook
  const unitElt = React.useMemo(() => {
    if (!unitInstance) unitInstance = createUnitElement();
    return unitInstance;
  }, []);
  const unitEltRef = React.useRef<HTMLDivElement | null>(unitElt);

  useResizeObserver({
    ref: unitEltRef,
    onResize: ({ entry }) => {
      if (!entry) return;
      const newFactor = entry.borderBoxSize
      ? entry.borderBoxSize[0].inlineSize
      : (entry.target as HTMLElement).offsetWidth;
      setFactor(newFactor);
    },
  });

  return factor;
};

export default useRemFactor;
